// Greedy-argmax threshold: multithreading only pays off for large d.
#define MM_PARALLEL_MIN_D 512
#define MM_GRAIN 64

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d < MM_PARALLEL_MIN_D) {
        matmul_rows(xout, x, w, n, 0, d);
        return;
    }

    // Partition rows into 4-row-aligned chunks for dispatch_apply.
    int nchunks = (d + MM_GRAIN - 1) / MM_GRAIN;
    int chunk = ((d + nchunks - 1) / nchunks + 3) & ~3;
    int total = (d + chunk - 1) / chunk;

    dispatch_apply(total, DISPATCH_APPLY_AUTO, ^(size_t k) {
        int i0 = (int)k * chunk;
        int i1 = i0 + chunk;
        if (i1 > d) i1 = d;
        matmul_rows(xout, x, w, n, i0, i1);
    });
}
